/** Public installation metadata and small derivatives of the existing native Pigeon icon. */
export const BROWSER_APP_MANIFEST = {
 id: '/app', name: 'Pigeon', short_name: 'Pigeon',
 description: 'Read your newsletters and feeds with Pigeon.',
 start_url: '/app', scope: '/app', display: 'standalone',
 theme_color: '#f5f5f2', background_color: '#f5f5f2',
 icons: [
  { src: '/app/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
  { src: '/app/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
 ],
};

// Derived with sips -z <size> <size> <native AppIcon-1024.png> --out <temporary PNG>.
// Native source SHA256: db3a5b8debddfc3fec526281374d45a8decc068293e5c9ff49e0c766cc77b3f9.
// Native originals are unchanged. Embedded because the Worker has no filesystem.
const ICON_192 = '';
const ICON_512 = '';
const iconBytes = new Map<number, Uint8Array<ArrayBuffer>>();

export function handleBrowserInstallationAsset(request: Request): Response {
 const path = new URL(request.url).pathname;
 const manifest = path === '/app/manifest.webmanifest';
 const size = path === '/app/icon-192.png' ? 192 : path === '/app/icon-512.png' || path === '/app/icon.png' ? 512 : 0;
 if (!manifest && !size) return new Response('Not found', { status: 404 });
 if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Method not allowed', { status: 405, headers: { Allow: 'GET, HEAD' } });
 const headers = { 'Content-Type': manifest ? 'application/manifest+json; charset=utf-8' : 'image/png', 'Cache-Control': 'public, max-age=3600', 'X-Content-Type-Options': 'nosniff' };
 if (request.method === 'HEAD') return new Response(null, { headers });
 if (manifest) return new Response(JSON.stringify(BROWSER_APP_MANIFEST), { headers });
 let bytes = iconBytes.get(size);
 if (!bytes) { const raw = atob(size === 192 ? ICON_192 : ICON_512); bytes = new Uint8Array(raw.length); for (let index = 0; index < raw.length; index++) bytes[index] = raw.charCodeAt(index); iconBytes.set(size, bytes); }
 return new Response(bytes, { headers });
}
